// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.prank(address(c).call(abi.encodeWithSignature("owner()")));
        try c.setOwner(newOwner) returns (bool success) {
            assertTrue(success);
        } catch {
            // Revert means the call failed for other reasons, not our concern.
            assertTrue(true);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // The owner is the test contract itself (deployer of C).
        // The fuzzer provides any new owner address.
        // We bound to avoid addresses that may cause collisions, but keep the domain wide.
        vm.assume(newOwner != address(0));

        // Owner calls setOwner, capture success via low-level call to get return data.
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
        require(success, "Call itself reverted unexpectedly");

        // Decode the bool return value.
        bool retVal = abi.decode(data, (bool));

        // Assert the general rule: the return value must be true after a successful owner call.
        // The correct contract always returns true; the mutant returns false for any input.
        assertTrue(retVal);
    }
}

