pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // The owner is set to this contract by setUp, so prank ourselves to act as owner.
        vm.prank(address(this));
        bool success = c.setOwner(_owner);
        assertTrue(success && c.owner() == _owner);
    }
}

